import re, collections
with open('/workspaces/semio/compose/sketchpad/sketchpad/Sketchpad.tsx') as f:
    lines = f.readlines()
decls = collections.defaultdict(list)
pattern = re.compile(r'^export\s+(?:interface|type|enum|const|function|class)\s+(\w+)')
for i, line in enumerate(lines, 1):
    m = pattern.match(line)
    if m:
        decls[m.group(1)].append(i)
dups = {k: v for k, v in decls.items() if len(v) > 1}
for name, locs in sorted(dups.items()):
    print(f'{name}: {locs}')
if not dups:
    print('No duplicates found!')
"

